<script setup>import {ref,computed,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {get,message} from '../services/api.js';const route=useRoute(),search=ref(''),data=ref([]),article=ref(null),error=ref(''),loading=ref(true);async function load(){loading.value=true;error.value='';try{if(route.params.slug)article.value=(await get('/guides/'+route.params.slug)).data;else{article.value=null;data.value=(await get('/guides')).data;}}catch(e){error.value=message(e);}finally{loading.value=false;}}const shown=computed(()=>{const t=search.value.trim().toLowerCase();return data.value.filter(g=>!t||[g.title,g.excerpt,...(g.tags||[])].join(' ').toLowerCase().includes(t));});watch(()=>route.fullPath,load);onMounted(load);</script>
<template><div class="container section"><p v-if="error" class="error-box">{{error}}</p><div v-else-if="loading" class="grid" aria-label="Loading guides"><div v-for="n in 3" :key="n" class="skeleton"></div></div><template v-else-if="article"><nav class="bread"><RouterLink to="/">Home</RouterLink> / <RouterLink to="/guides">Guides</RouterLink> / {{article.title}}</nav><div class="page-head reading"><p class="eyebrow muted">{{article.readTimeMinutes}} min read</p><h1>{{article.title}}</h1><p>{{article.excerpt}}</p></div><div class="guide-layout"><img class="guide-cover" src="/images/photos/table.jpg" alt="A carefully plated restaurant meal" loading="lazy"><article class="reading guide-steps"><section v-for="(p,i) in article.body.split('\n\n')" :key="i" class="card pad"><p class="eyebrow">{{String(i+1).padStart(2,'0')}}</p><p>{{p}}</p></section></article></div><RouterLink to="/countries" class="btn secondary">Explore country guides</RouterLink></template><template v-else><div class="page-head"><h1>Read before you eat</h1><p>Short guides to scores, meal times and dining customs.</p></div><div class="toolbar"><div class="search-wrap"><label class="sr-only" for="guide-search">Search guides</label><input id="guide-search" v-model="search" type="search" placeholder="Search guides" autocomplete="off"><button v-if="search" type="button" class="clear-x" aria-label="Clear search" @click="search=''">×</button></div><span class="meta-count" role="status" aria-live="polite">{{shown.length}} of {{data.length}} guides</span></div><div v-if="!shown.length" class="card empty-results"><h2>No guides match</h2><p class="muted">Try another word.</p><div class="row"><button class="cta" @click="search=''">Clear search</button></div></div><div class="grid stagger"><article v-for="(g,gi) in shown" :style="{'--i':gi}" :key="g.slug" class="card guide-card"><img class="editorial-photo" :src="'/images/photos/'+(['table','sushi','dining','pasta'][data.indexOf(g)%4])+'.jpg'" :alt="'Dining inspiration for '+g.title" loading="lazy"><div class="pad"><p class="eyebrow muted">{{g.readTimeMinutes}} min read</p><h2>{{g.title}}</h2><p>{{g.excerpt}}</p><RouterLink :to="'/guides/'+g.slug" class="btn secondary">Read guide</RouterLink></div></article></div></template></div></template>

<style scoped>.guide-layout{display:grid;grid-template-columns:1fr 1.6fr;gap:40px;margin-bottom:32px}.guide-cover{width:100%;aspect-ratio:4/5;object-fit:cover;border-radius:24px;position:sticky;top:180px}.guide-steps{display:grid;gap:20px}.guide-steps p:last-child{margin-bottom:0}.guide-card{display:flex;flex-direction:column}.guide-card>.pad{display:flex;flex:1;flex-direction:column;align-items:start}.guide-card .btn{margin-top:auto}@media(max-width:900px){.guide-layout{grid-template-columns:1fr}.guide-cover{position:static;aspect-ratio:16/7}}</style>
